const axios = require("axios")

/**
 * Buscar videos en TikTok
 * @param {string} text
 * @returns {Promise<{text?: string, results?: Array, error?: string}>}
 */
async function ttsearch(text) {
  try {
    if (!text) {
      return { error: "Escribí algo para buscar" }
    }

    const { data } = await axios.get("https://www.tikwm.com/api/feed/search", {
      params: {
        keywords: text
      }
    })

    // Validación de datos
    if (!data?.data?.videos?.length) {
      return { error: "No se encontraron resultados" }
    }

    // Tomamos máximo 5 resultados
    const videos = data.data.videos.slice(0, 5)

    // Formateo de resultados
    const results = videos.map(v => ({
      title: v.title || "Sin título",
      author: v.author?.nickname || "Desconocido",
      username: v.author?.unique_id || "unknown",
      videoId: v.video_id,
      link: `https://www.tiktok.com/@${v.author?.unique_id}/video/${v.video_id}`
    }))

   
    return {
      result: results
    }

  } catch (err) {
    console.error("Error en ttsearch:", err)
    return { error: "Error al buscar en TikTok" }
  }
}

module.exports = { ttsearch }